  const refreshBillingCatalog = async () => {
    try {
      const catRes = await posService.getCatalog();
      const catalogData = (catRes.data || []).map(i => ({ 
        ...i, 
        stock: i.stock_count !== null ? parseInt(i.stock_count) : undefined,
        tax_applicable: !!i.tax_applicable,
        kot_category: i.kot_category || "Main Kitchen"
      }));
      setCatalog(catalogData);
      window.catalog = catalogData;
      setCategories(['All', ...new Set(catalogData.map(i => i.category).filter(Boolean))]);
    } catch (err) {
      console.error("Failed to refresh catalog:", err);
    }
  };

  const handleToggleItemMgmtAvailability = async (item) => {
    const nextAvailability = !item.availability;
    try {
      await posService.updateMenuItem(item.id, { availability: nextAvailability });
      setItemMgmtItems(prev => prev.map(i => i.id === item.id ? { ...i, availability: nextAvailability } : i));
      if (item.item_type === '0') {
        setCatalog(prev => prev.map(c => c.id === item.id ? { ...c, availability: nextAvailability } : c));
        await refreshBillingCatalog();
      }
      toast.success(`"${item.product_name}" availability updated`);
    } catch (err) {
      console.error('Failed to update availability:', err);
      toast.error('Failed to update availability');
    }
  };

  const handleDeleteItemMgmt = async (itemId, itemType, itemName) => {
    if (!window.confirm(`Are you sure you want to delete "${itemName}"?`)) return;
    try {
      await posService.deleteMenuItem(itemId);
      setItemMgmtItems(prev => prev.filter(i => i.id !== itemId));
      if (itemType === '0') {
        setCatalog(prev => prev.filter(c => c.id !== itemId));
        await refreshBillingCatalog();
      }
      toast.success('Item deleted successfully');
    } catch (err) {
      console.error('Failed to delete item:', err);
      toast.error('Failed to delete item');
    }
  }
